// Coge la imagen más grande del correo (la captura del informe) y la deja como archivo para adjuntar
const correos = $('Solo suscripción Power BI').all();
const fecha = $now.setZone('Europe/Madrid').toFormat('yyyy-MM-dd');
const resultado = [];

$input.all().forEach((item, i) => {
  const correo = correos[i]?.json ?? {};
  const imagenes = (item.json.value || [])
    .filter(a => String(a.contentType || '').toLowerCase().startsWith('image/') && a.contentBytes)
    .sort((a, b) => (b.size || 0) - (a.size || 0));

  if (!imagenes.length) return;

  const img = imagenes[0];
  const tipo = String(img.contentType).toLowerCase();
  const ext = tipo.includes('jpeg') || tipo.includes('jpg') ? 'jpg' : (tipo.split('/')[1] || 'png');
  const informe = String(correo.subject || 'Informe')
    .replace(/^[\s;:,]*/, '')
    .replace(/^subscription for\s*/i, '')
    .replace(/[\\/:*?"<>|]/g, '')
    .trim() || 'Informe';
  const nombreArchivo = `${informe} - ${fecha}.${ext}`;

  resultado.push({
    json: { message_id: correo.id, informe, fecha, nombre_archivo: nombreArchivo },
    binary: { informe: { data: img.contentBytes, mimeType: tipo, fileName: nombreArchivo } },
    pairedItem: i
  });
});

return resultado;

